1	/**
2	 * Attachment metadata plus the storage quota guard.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit
5	 */
6	import { wouldExceedLimit } from "@/config/plan-limits";
7	import { assertCan } from "@/lib/permissions";
8	import { assertOrgScope } from "@/lib/tenant";
9	import * as attachmentRepo from "@/server/repositories/attachment-repository";
10	import * as issueRepo from "@/server/repositories/issue-repository";
11	import * as orgRepo from "@/server/repositories/organization-repository";
12	import * as usageRepo from "@/server/repositories/usage-repository";
13	import { issueResource, requireFound } from "./_support";
14	import type {
15	  CreateAttachmentInput,
16	  DeleteAttachmentInput,
17	} from "@/schemas/attachment";
18	import type { IssueId, OrgId } from "@/types/common";
19	import type { IssueAttachment } from "@/types/issue";
20	import type { Actor } from "@/types/member";
21	
22	const BYTES_PER_MB = 1024 * 1024;
23	
24	export async function listAttachments(
25	  actor: Actor,
26	  orgId: OrgId,
27	  issueId: IssueId,
28	): Promise<readonly IssueAttachment[]> {
29	  assertOrgScope(actor, orgId);
30	
31	  const issue = requireFound(
32	    await issueRepo.findIssueById(orgId, issueId),
33	    "Issue",
34	    issueId,
35	  );
36	  assertCan(actor, "issue:read", issueResource(issue));
37	
38	  return attachmentRepo.listAttachments(orgId, issueId);
39	}
40	
41	/**
42	 * Records an upload after checking the org still has storage left. The quota
43	 * is in megabytes and the upload is in bytes, so the incoming size is rounded
44	 * up to whole megabytes before the comparison — half a megabyte still costs
45	 * one against the plan.
46	 */
47	export async function addAttachment(
48	  actor: Actor,
49	  input: CreateAttachmentInput,
50	): Promise<IssueAttachment> {
51	  assertOrgScope(actor, input.orgId);
52	
53	  const issue = requireFound(
54	    await issueRepo.findIssueById(input.orgId, input.issueId),
55	    "Issue",
56	    input.issueId,
57	  );
58	  assertCan(actor, "issue:update", issueResource(issue));
59	
60	  const org = requireFound(
61	    await orgRepo.findOrgById(input.orgId),
62	    "Organization",
63	    input.orgId,
64	  );
65	
66	  const usage = await usageRepo.getUsage(input.orgId);
67	  const requestedMb = Math.ceil(input.sizeBytes / BYTES_PER_MB);
68	
69	  if (
70	    wouldExceedLimit(org.plan, "storageMb", usage.storageMbUsed, requestedMb)
71	  ) {
72	    throw new Error(
73	      `Plan ${org.plan} has no room for another ${requestedMb} MB`,
74	    );
75	  }
76	
77	  const attachment = await attachmentRepo.insertAttachment(
78	    input,
79	    actor.userId,
80	  );
81	  await usageRepo.incrementUsage(input.orgId, { storageMbUsed: requestedMb });
82	
83	  return attachment;
84	}
85	
86	/** Removing an attachment gives the megabytes back to the quota. */
87	export async function removeAttachment(
88	  actor: Actor,
89	  input: DeleteAttachmentInput,
90	): Promise<void> {
91	  assertOrgScope(actor, input.orgId);
92	
93	  const attachment = requireFound(
94	    await findAttachment(input.orgId, input.attachmentId),
95	    "Attachment",
96	    input.attachmentId,
97	  );
98	
99	  const issue = requireFound(
100	    await issueRepo.findIssueById(input.orgId, attachment.issueId),
101	    "Issue",
102	    attachment.issueId,
103	  );
104	  assertCan(actor, "issue:update", issueResource(issue));
105	
106	  await attachmentRepo.deleteAttachment(input.orgId, input.attachmentId);
107	  await usageRepo.incrementUsage(input.orgId, {
108	    storageMbUsed: -Math.ceil(attachment.sizeBytes / BYTES_PER_MB),
109	  });
110	}
111	
112	/**
113	 * The attachment repository only reads by issue, because that is the only way
114	 * the UI ever reaches one. A delete arrives with just an id, so the org's
115	 * issues are walked until the row turns up.
116	 */
117	async function findAttachment(
118	  orgId: OrgId,
119	  attachmentId: string,
120	): Promise<IssueAttachment | null> {
121	  const page = await issueRepo.listIssues({
122	    orgId,
123	    limit: 100,
124	    cursor: null,
125	    includeArchived: true,
126	  });
